contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0));
        require(amount > 0);

        // Approve ourselves so a correct ERC20-like token could still revert only on roles, not allowance
        c.approve(address(this), amount);

        bool revertedTransfer;
        try c.transfer(recipient, amount) {
            revertedTransfer = false;
        } catch {
            revertedTransfer = true;
        }

        bool revertedTransferFrom;
        try c.transferFrom(address(this), recipient, amount) {
            revertedTransferFrom = false;
        } catch {
            revertedTransferFrom = true;
        }

        // Rule: since neither party is an allowed role, both transfers must revert.
        // A faulty version without the role check (e.g. a plain ERC20) would succeed here.
        assert(revertedTransfer && revertedTransferFrom);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0));
        require(recipient != address(this));
        require(amount > 0);
        require(amount < c.minTxnAmount());

        uint256 senderBalBefore = c.balanceOf(address(this));
        require(senderBalBefore >= amount);
        uint256 recipBalBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 senderBalAfter = c.balanceOf(address(this));
        uint256 recipBalAfter = c.balanceOf(recipient);

        assert(
            !reverted &&
            senderBalAfter == senderBalBefore - amount &&
            recipBalAfter == recipBalBefore + amount
        );
    }

    receive() external payable {}
}

