contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address attacker, uint256 newMin) public {
        require(attacker != c.owner());
        require(newMin != c.minTxnAmount());

        uint256 before = c.minTxnAmount();

        bool revertedNonOwner;
        bool ok1;
        try c.setMinTxnAmount(newMin) {
            revertedNonOwner = false;
            ok1 = true;
        } catch {
            revertedNonOwner = true;
            ok1 = false;
        }
        // ensure the try block path also executes a state change safely if it succeeded
        if (!ok1) {
            // non-owner (this contract is msg.sender, not owner) - expect revert; nothing to do
        }

        // We (the test contract) are not the owner, so c.owner() is the deployer,
        // not address(this). Verify ownership transfer so the second phase works.
        c.changeOwner(address(this));

        c.setMinTxnAmount(newMin);
        uint256 afterOwner = c.minTxnAmount();

        assert(revertedNonOwner && before == c.minTxnAmount() - (newMin - afterOwner) && afterOwner == newMin);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newRate) public {
        uint256 before = c.rewardRate();
        require(newRate != before);

        // As a non-owner (this contract is not the deployer/owner), the call must revert
        bool revertedNonOwner;
        try c.setRewardRate(newRate) {
            revertedNonOwner = false;
        } catch {
            revertedNonOwner = true;
        }

        uint256 mid = c.rewardRate();

        // Acquire ownership and verify the owner's call succeeds and updates the value
        c.changeOwner(address(this));
        c.setRewardRate(newRate);
        uint256 afterOwner = c.rewardRate();

        assert(revertedNonOwner && mid == before && afterOwner == newRate);
    }

    receive() external payable {}
}

