contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(this) && recipient != address(c));
        require(amount > 0);

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipBefore = c.balanceOf(recipient);

        bool reverted;
        if (amount <= senderBefore) {
            c.transfer(recipient, amount);
            reverted = false;
        } else {
            reverted = true;
        }

        if (!reverted) {
            uint256 senderAfter = c.balanceOf(address(this));
            uint256 recipAfter = c.balanceOf(recipient);
            assert(recipAfter == recipBefore + amount && senderBefore == senderAfter + amount);
        } else {
            // over-balance transfers must revert and leave balances unchanged
            uint256 senderAfter = c.balanceOf(address(this));
            uint256 recipAfter = c.balanceOf(recipient);
            assert(senderAfter == senderBefore && recipAfter == recipBefore);
        }
    }

    receive() external payable {}
}

