contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 amount, uint256 subtractedValue) public {
        require(spender != address(0));
        c.approve(spender, amount);
        uint256 afterApprove = c.allowance(address(this), spender);
        bool reverted;
        if (subtractedValue <= amount) {
            c.decreaseAllowance(spender, subtractedValue);
            reverted = false;
        } else {
            try c.decreaseAllowance(spender, subtractedValue) { reverted = false; }
            catch { reverted = true; }
        }
        uint256 finalAllowance = c.allowance(address(this), spender);
        if (reverted) {
            assert(finalAllowance == afterApprove && afterApprove == amount);
        } else {
            assert(finalAllowance == amount - subtractedValue && afterApprove == amount);
        }
    }
    receive() external payable {}
}

