contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 initial, uint256 dec) public {
        require(spender != address(0));
        require(initial > 0 && dec > 0);

        c.approve(spender, initial);

        bool revertedLow;
        uint256 afterLow;
        if (dec <= initial) {
            bool ok = c.decreaseAllowance(spender, dec);
            revertedLow = !ok;
            afterLow = c.allowance(address(this), spender);
        } else {
            try c.decreaseAllowance(spender, dec) {
                revertedLow = false;
            } catch {
                revertedLow = true;
            }
            afterLow = c.allowance(address(this), spender);
        }

        if (dec <= initial) {
            assert(!revertedLow && afterLow == initial - dec);
        } else {
            assert(revertedLow && afterLow == initial);
        }
    }

    receive() external payable {}
}

