        bool reverted;
        try c.setMinTxnAmount(newMin) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 minAfter = c.minTxnAmount();

        assert(
            ownerBefore == address(this) &&
            ownerAfter == newOwner &&
            reverted &&
            minAfter == minBefore
        );
    }

    receive() external payable {}
}

