contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 initial, uint256 added) public {
        require(spender != address(0));
        require(initial <= type(uint256).max - added);

        c.approve(spender, initial);
        uint256 before = c.allowance(address(this), spender);

        bool reverted;
        try c.increaseAllowance(spender, added) { reverted = false; } catch { reverted = true; }

        assert(!reverted && c.allowance(address(this), spender) == before + added);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 amount) public payable {
        require(spender != address(0), "zero spender");
        c.approve(spender, amount);
        uint256 allowed = c.allowance(address(this), spender);
        uint256 before = c.allowance(address(this), spender);
        bool reverted;
        if (amount == type(uint256).max) {
            reverted = true;
        } else {
            c.transferFrom(address(this), spender, amount + 1);
            reverted = false;
        }
        assert(allowed == amount && before == amount && reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(this), "new owner must differ from test contract");
        address ownerBefore = c.owner();
        bool secondReverted;
        c.changeOwner(newOwner);
        address ownerAfter = c.owner();
        try c.changeOwner(address(this)) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assert(ownerBefore == address(this) && ownerAfter == newOwner && secondReverted && c.owner() == newOwner);
    }
    receive() external payable {}
}
